import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Kernel: C = triu(A @ B), where A (M,K) and B (K,N) are row-major upper-triangular
// matrices. Uses the triangular structure to:
//   1) skip entire tiles that lie strictly below the diagonal (they are all zero)
//   2) restrict the K-reduction range to only the part that can contribute to
//      the given output tile
//   3) mask (triu) only the diagonal tiles where partial masking is required.
template <class T>
__global__ static void triu_matmul_kernel(
    int M, int N, int K,
    T const* __restrict__ A,
    T const* __restrict__ B,
    T* __restrict__ C)
{
  constexpr int BM = 128;
  constexpr int BN = 128;
  constexpr int BK = 8;

  int row_tile = blockIdx.x;   // tile index along M
  int col_tile = blockIdx.y;   // tile index along N

  // Global tensors, row-major layouts matching PyTorch's contiguous storage.
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, Int<1>{}));      // A(m,k)
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), make_stride(Int<1>{}, N));       // B^T view: mB(n,k)=B(k,n)
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, Int<1>{}));       // C(m,n)

  auto cta_tiler = make_shape(Int<BM>{}, Int<BN>{}, Int<BK>{});
  auto cta_coord = make_coord(row_tile, col_tile, _);

  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1, X, _1>{});   // (BM,BK,KTILES)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X, _1, _1>{});   // (BN,BK,KTILES)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1, _1, X>{});   // (BM,BN)

  // Coordinate ("identity") tensor for masking global (row,col) indices.
  Tensor cCoord = make_identity_tensor(make_shape(M, N));
  Tensor gCoord = local_tile(cCoord, cta_tiler, cta_coord, Step<_1, _1, X>{});  // (BM,BN)

  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));

  Tensor tCgC     = local_partition(gC,     tC, threadIdx.x, Step<_1, _1>{});
  Tensor tCgCoord = local_partition(gCoord, tC, threadIdx.x, Step<_1, _1>{});

  // Tiles that lie strictly below the diagonal are all-zero: fill and exit early.
  if (col_tile < row_tile) {
    clear(tCgC);
    return;
  }

  __shared__ T smemA[2 * BM * BK];
  __shared__ T smemB[2 * BN * BK];
  Tensor sA0 = make_tensor(make_smem_ptr(smemA), make_shape(Int<BM>{}, Int<BK>{}));
  Tensor sA1 = make_tensor(make_smem_ptr(smemA + BM * BK), make_shape(Int<BM>{}, Int<BK>{}));
  Tensor sB0 = make_tensor(make_smem_ptr(smemB), make_shape(Int<BN>{}, Int<BK>{}));
  Tensor sB1 = make_tensor(make_smem_ptr(smemB + BN * BK), make_shape(Int<BN>{}, Int<BK>{}));
  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);
  using TAsA_t = decltype(local_partition(sA0, tA, threadIdx.x));
  TAsA_t tAsA[2] = {
      local_partition(sA0, tA, threadIdx.x),
      local_partition(sA1, tA, threadIdx.x)
  };
  using TBsB_t = decltype(local_partition(sB0, tB, threadIdx.x));
  TBsB_t tBsB[2] = {
      local_partition(sB0, tB, threadIdx.x),
      local_partition(sB1, tB, threadIdx.x)
  };
  using TCsA_t = decltype(local_partition(sA0, tC, threadIdx.x, Step<_1, X>{}));
  TCsA_t tCsA[2] = {
      local_partition(sA0, tC, threadIdx.x, Step<_1, X>{}),
      local_partition(sA1, tC, threadIdx.x, Step<_1, X>{})
  };
  using TCsB_t = decltype(local_partition(sB0, tC, threadIdx.x, Step<X, _1>{}));
  TCsB_t tCsB[2] = {
      local_partition(sB0, tC, threadIdx.x, Step<X, _1>{}),
      local_partition(sB1, tC, threadIdx.x, Step<X, _1>{})
  };
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  // Restrict the K-tile range: only k in [row_tile*BM, (col_tile+1)*BN) can
  // contribute non-zero terms, because A(m,k)=0 for k<m and B(k,n)=0 for k>n.
  int k_lo = row_tile * BM;
  int k_hi = (col_tile + 1) * BN;
  if (k_hi > K) k_hi = K;
  int k_tile_start = k_lo / BK;
  int k_tile_end   = (k_hi + BK - 1) / BK;
  int num_tiles    = k_tile_end - k_tile_start;
  // Software-pipelined (double-buffered) main loop: prefetch the next K-tile
  // via cp.async while computing on the currently resident tile, hiding
  // global memory latency behind the GEMM compute.
  copy(tAgA(_, _, k_tile_start), tAsA[0]);
  copy(tBgB(_, _, k_tile_start), tBsB[0]);
  cp_async_fence();
  int buf = 0;
  for (int idx = 0; idx < num_tiles; ++idx) {
    int k_tile = k_tile_start + idx;
    int next_idx = idx + 1;
    int nbuf = 1 - buf;
    if (next_idx < num_tiles) {
      copy(tAgA(_, _, k_tile_start + next_idx), tAsA[nbuf]);
      copy(tBgB(_, _, k_tile_start + next_idx), tBsB[nbuf]);
      cp_async_fence();
      cp_async_wait<1>();
    } else {
      cp_async_wait<0>();
    }
    __syncthreads();
    gemm(tCsA[buf], tCsB[buf], tCrC);
    __syncthreads();
    buf = nbuf;
  }

  // Diagonal tiles need element-wise masking (upper-triangular part only).
  if (row_tile == col_tile) {
    CUTE_UNROLL
    for (int i = 0; i < int(size<0>(tCrC)); ++i) {
      CUTE_UNROLL
      for (int j = 0; j < int(size<1>(tCrC)); ++j) {
        auto coord = tCgCoord(i, j);
        int gi = get<0>(coord);
        int gj = get<1>(coord);
        if (gi > gj) {
          tCrC(i, j) = T(0);
        }
      }
    }
  }

  axpby(T(1), tCrC, T(0), tCgC);
}

torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int K2 = (int)B.size(0);
  int N = (int)B.size(1);
  TORCH_CHECK(K == K2, "Inner dimensions of A and B must match");

  constexpr int BM = 128, BN = 128, BK = 8;
  TORCH_CHECK(M % BM == 0 && N % BN == 0 && K % BK == 0,
              "Dimensions must be multiples of the tile size (128,128,8)");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C = torch::empty({M, N}, A.options());

  dim3 block(256);
  dim3 grid((unsigned)(M / BM), (unsigned)(N / BN));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  triu_matmul_kernel<float><<<grid, block, 0, stream>>>(
      M, N, K,
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>());

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "triu_matmul_kernel launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

triu_ext = load_inline(
    name="cute_triu_matmul_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["triu_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Computes C = triu(A @ B) for upper triangular square matrices using a
    single fused CUTE kernel that exploits the triangular structure to skip
    entirely-zero output tiles and restrict the K-reduction range.
    """
    def __init__(self) -> None:
        super().__init__()
        self._ext = triu_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.triu_matmul(A.contiguous(), B.contiguous())

